import{_ as a,a as o,c as n,ac as t}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · 全册易错点 · 第22–44课","description":"逐课检查常见错误、适用边界和正确表达。","frontmatter":{"title":"第三册：培养技能 · 全册易错点 · 第22–44课","description":"逐课检查常见错误、适用边界和正确表达。","splitFrom":"life/english/new-concept/book-3/mistakes.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"句法与表达查阅","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第三册：培养技能 · 全册易错点","summary":"逐课检查常见错误、适用边界和正确表达。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · 全册易错点 · 第1–21课","link":"/life/english/new-concept/book-3/mistakes-part-01"},"next":{"text":"第三册：培养技能 · 全册易错点 · 第45–60课","link":"/life/english/new-concept/book-3/mistakes-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · 全册易错点 · 第1–21课","link":"/life/english/new-concept/book-3/mistakes-part-01"},"next":{"text":"第三册：培养技能 · 全册易错点 · 第45–60课","link":"/life/english/new-concept/book-3/mistakes-part-03"}},"headers":[],"relativePath":"life/english/new-concept/book-3/mistakes-part-02.md","filePath":"life/english/new-concept/book-3/mistakes-part-02.md"}'),i={name:"life/english/new-concept/book-3/mistakes-part-02.md"};function s(r,e,l,h,p,d){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="第三册-培养技能-·-全册易错点-·-第22–44课" tabindex="-1">第三册：培养技能 · 全册易错点 · 第22–44课 <a class="header-anchor" href="#第三册-培养技能-·-全册易错点-·-第22–44课" aria-label="Permalink to &quot;第三册：培养技能 · 全册易错点 · 第22–44课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/mistakes">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-3/overview">本册介绍</a> · <a href="/life/english/new-concept/book-3/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-3/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-3/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-3/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-3/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-3/review">综合复习与自测</a></p><h2 id="l22-·-should-have-done-的过去评价" tabindex="-1">L22 · should have done 的过去评价 <a class="header-anchor" href="#l22-·-should-have-done-的过去评价" aria-label="Permalink to &quot;L22 · should have done 的过去评价 {#l22-·-should-have-done-的过去评价}&quot;">​</a></h2><p>I should checked 错缺 have；过去评价用 should have checked，当前建议用 should check。</p><p><strong>对照例句：</strong> I missed my cue because I had not rehearsed; I should have checked the recording twice.</p><p>had not rehearsed 交代此前缺失的准备；should have checked 评价未完成的适当行动。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-022">回看讲解和练习</a></p><h2 id="l23-·-prefer-与-would-rather" tabindex="-1">L23 · prefer 与 would rather <a class="header-anchor" href="#l23-·-prefer-与-would-rather" aria-label="Permalink to &quot;L23 · prefer 与 would rather {#l23-·-prefer-与-would-rather}&quot;">​</a></h2><p>I prefer tea than coffee 应改为 prefer tea to coffee；would rather drink tea than coffee 是另一结构。</p><p><strong>对照例句：</strong> I prefer tasting a small portion to rejecting an unfamiliar dish immediately.</p><p>tasting 与 rejecting 为平行动名词结构；to 是介词而非不定式标记。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-023">回看讲解和练习</a></p><h2 id="l24-·-同位语从句与定语从句" tabindex="-1">L24 · 同位语从句与定语从句 <a class="header-anchor" href="#l24-·-同位语从句与定语从句" aria-label="Permalink to &quot;L24 · 同位语从句与定语从句 {#l24-·-同位语从句与定语从句}&quot;">​</a></h2><p>The letter that was unsigned 中 that 作从句主语；the fact that the letter was unsigned 中 that 不作句子成分。</p><p><strong>对照例句：</strong> The discovery that the letter was unsigned raised new questions.</p><p>that the letter was unsigned 说明 discovery 的具体内容；从句不缺主语或表语。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-024">回看讲解和练习</a></p><h2 id="l25-·-过去完成进行时" tabindex="-1">L25 · 过去完成进行时 <a class="header-anchor" href="#l25-·-过去完成进行时" aria-label="Permalink to &quot;L25 · 过去完成进行时 {#l25-·-过去完成进行时}&quot;">​</a></h2><p>had been sailed 是被动形式的一部分，不等于 had been sailing；主动进行需要 ing。</p><p><strong>对照例句：</strong> The crew had been sailing for six hours when the wind finally changed.</p><p>had been sailing 强调风变前的持续过程；when 从句提供过去参照点。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-025">回看讲解和练习</a></p><h2 id="l26-·-too-与-enough-的位置" tabindex="-1">L26 · too 与 enough 的位置 <a class="header-anchor" href="#l26-·-too-与-enough-的位置" aria-label="Permalink to &quot;L26 · too 与 enough 的位置 {#l26-·-too-与-enough-的位置}&quot;">​</a></h2><p>enough wide 应为 wide enough；wide enough space 则应根据所指改写为 enough space 或 a sufficiently wide space。</p><p><strong>对照例句：</strong> The tin is wide enough to hold the cards, but it is too shallow for the wooden pieces.</p><p>enough 在 wide 后；too 在 shallow 前；两个评价分别针对不同物品。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-026">回看讲解和练习</a></p><h2 id="l27-·-不定代词的后置修饰" tabindex="-1">L27 · 不定代词的后置修饰 <a class="header-anchor" href="#l27-·-不定代词的后置修饰" aria-label="Permalink to &quot;L27 · 不定代词的后置修饰 {#l27-·-不定代词的后置修饰}&quot;">​</a></h2><p>I don&#39;t need nothing 在标准书面英语里应改为 I don&#39;t need anything；not everything 不是“什么都不”。</p><p><strong>对照例句：</strong> We found nothing expensive in the cabin, but there was everything we needed.</p><p>expensive 后置修饰 nothing；everything 后接省略宾语关系词的限定从句 we needed。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-027">回看讲解和练习</a></p><h2 id="l28-·-条件句中的礼貌距离" tabindex="-1">L28 · 条件句中的礼貌距离 <a class="header-anchor" href="#l28-·-条件句中的礼貌距离" aria-label="Permalink to &quot;L28 · 条件句中的礼貌距离 {#l28-·-条件句中的礼貌距离}&quot;">​</a></h2><p>I would consider to buy 应为 consider buying；consider 后接动名词，不能直接接 to do 表示考虑做某事。</p><p><strong>对照例句：</strong> If you included the carrying case, I would consider paying the full price.</p><p>included 与 would consider 构成试探性条件；consider 不等于作出购买承诺。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-028">回看讲解和练习</a></p><h2 id="l29-·-whether-从句与选择范围" tabindex="-1">L29 · whether 从句与选择范围 <a class="header-anchor" href="#l29-·-whether-从句与选择范围" aria-label="Permalink to &quot;L29 · whether 从句与选择范围 {#l29-·-whether-从句与选择范围}&quot;">​</a></h2><p>Whether does the joke work depends ... 错在从句倒装；应保持 the joke works 的陈述语序。</p><p><strong>对照例句：</strong> Whether the joke works depends partly on what the audience already knows.</p><p>whether 从句整体作主语，谓语为单数 depends；what 从句作 on 的宾语。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-029">回看讲解和练习</a></p><h2 id="l30-·-情态动词加完成式推断" tabindex="-1">L30 · 情态动词加完成式推断 <a class="header-anchor" href="#l30-·-情态动词加完成式推断" aria-label="Permalink to &quot;L30 · 情态动词加完成式推断 {#l30-·-情态动词加完成式推断}&quot;">​</a></h2><p>He must opened 错缺 have；He had to open 表示过去不得不打开，意义不是过去推断。</p><p><strong>对照例句：</strong> Someone must have opened the cupboard, because the flour had been moved.</p><p>must have opened 是基于线索的推断，because 从句给出依据；推断仍不同于亲眼观察。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-030">回看讲解和练习</a></p><h2 id="l31-·-非限定性定语从句" tabindex="-1">L31 · 非限定性定语从句 <a class="header-anchor" href="#l31-·-非限定性定语从句" aria-label="Permalink to &quot;L31 · 非限定性定语从句 {#l31-·-非限定性定语从句}&quot;">​</a></h2><p>Mr Vale, that repairs clocks, ... 不符合非限定从句规则，应使用 who，并补足完整主句。</p><p><strong>对照例句：</strong> Mr Vale, who repairs clocks for fun, keeps a tiny workshop in his kitchen.</p><p>who 从句补充已明确人物的爱好；主句骨架为 Mr Vale keeps a tiny workshop。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-031">回看讲解和练习</a></p><h2 id="l32-·-现在完成时被动" tabindex="-1">L32 · 现在完成时被动 <a class="header-anchor" href="#l32-·-现在完成时被动" aria-label="Permalink to &quot;L32 · 现在完成时被动 {#l32-·-现在完成时被动}&quot;">​</a></h2><p>The wreck has discovered 缺少被动的 been，应为 has been discovered；若由研究者主动发现，则主语需改为 researchers。</p><p><strong>对照例句：</strong> Three wooden beams have been recovered, but the vessel has not yet been identified.</p><p>have been recovered 对应复数 beams；has not yet been identified 对应单数 vessel。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-032">回看讲解和练习</a></p><h2 id="l33-·-否定副词前置倒装" tabindex="-1">L33 · 否定副词前置倒装 <a class="header-anchor" href="#l33-·-否定副词前置倒装" aria-label="Permalink to &quot;L33 · 否定副词前置倒装 {#l33-·-否定副词前置倒装}&quot;">​</a></h2><p>Never I saw ... 缺少倒装；一般过去时应写 Never did I see ...，不能写 did I saw。</p><p><strong>对照例句：</strong> Never had I seen the station so quiet before that morning.</p><p>never 前置使 had 提到 I 前；seen 保持过去分词，before that morning 给出过去参照点。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-033">回看讲解和练习</a></p><h2 id="l34-·-分词状语的逻辑主语" tabindex="-1">L34 · 分词状语的逻辑主语 <a class="header-anchor" href="#l34-·-分词状语的逻辑主语" aria-label="Permalink to &quot;L34 · 分词状语的逻辑主语 {#l34-·-分词状语的逻辑主语}&quot;">​</a></h2><p>Looking under the table, a coin appeared 容易构成悬垂分词；应改为 I found a coin 或 When I looked ...。</p><p><strong>对照例句：</strong> Looking beneath the frame, Maya noticed a small handwritten label.</p><p>Looking 的逻辑主语为 Maya，与主句一致；分词短语交代发现时的动作背景。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-034">回看讲解和练习</a></p><h2 id="l35-·-情态动词的被动结构" tabindex="-1">L35 · 情态动词的被动结构 <a class="header-anchor" href="#l35-·-情态动词的被动结构" aria-label="Permalink to &quot;L35 · 情态动词的被动结构 {#l35-·-情态动词的被动结构}&quot;">​</a></h2><p>The statements should examined 缺 be；should be examined 仍不表示审查已经完成。</p><p><strong>对照例句：</strong> Both statements should be examined before a decision is announced.</p><p>should be examined 为建议性被动，before 后 is announced 描述流程中的另一步。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-035">回看讲解和练习</a></p><h2 id="l36-·-so-与-such-的结果结构" tabindex="-1">L36 · so 与 such 的结果结构 <a class="header-anchor" href="#l36-·-so-与-such-的结果结构" aria-label="Permalink to &quot;L36 · so 与 such 的结果结构 {#l36-·-so-与-such-的结果结构}&quot;">​</a></h2><p>so an unexpected meeting 位置错误；可写 such an unexpected meeting，或 the meeting was so unexpected。</p><p><strong>对照例句：</strong> It was such an unexpected meeting that neither of us spoke for a moment.</p><p>such 修饰 an unexpected meeting 这一名词短语；that 从句表达惊讶造成的反应。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-036">回看讲解和练习</a></p><h2 id="l37-·-by、until-与时刻表现在时" tabindex="-1">L37 · by、until 与时刻表现在时 <a class="header-anchor" href="#l37-·-by、until-与时刻表现在时" aria-label="Permalink to &quot;L37 · by、until 与时刻表现在时 {#l37-·-by、until-与时刻表现在时}&quot;">​</a></h2><p>Wait by six 不表示一直等到六点，持续等待应写 Wait until six；arrive until six 在此也不自然。</p><p><strong>对照例句：</strong> We must reach the platform by six, although the train does not leave until ten past.</p><p>by six 给到达截止时间；not ... until ten past 给列车最早实际离开时间。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-037">回看讲解和练习</a></p><h2 id="l38-·-目的不定式与-for-doing" tabindex="-1">L38 · 目的不定式与 for doing <a class="header-anchor" href="#l38-·-目的不定式与-for-doing" aria-label="Permalink to &quot;L38 · 目的不定式与 for doing {#l38-·-目的不定式与-for-doing}&quot;">​</a></h2><p>a tool for measure 应为 a tool for measuring；目的不定式则是 used it to measure。</p><p><strong>对照例句：</strong> The group marked a stone each evening to keep track of passing days.</p><p>marked 为主要动作，to keep track of 为目的；each evening 说明重复频率。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-038">回看讲解和练习</a></p><h2 id="l39-·-不定式后置修饰与介词" tabindex="-1">L39 · 不定式后置修饰与介词 <a class="header-anchor" href="#l39-·-不定式后置修饰与介词" aria-label="Permalink to &quot;L39 · 不定式后置修饰与介词 {#l39-·-不定式后置修饰与介词}&quot;">​</a></h2><p>I need someone to speak 应表达为 someone to speak to，若意思是“需要一个说话者”，则原结构可能有不同含义。</p><p><strong>对照例句：</strong> We had a reliable guide to consult and a marked path to follow.</p><p>consult 与 follow 都直接带宾语，因此不定式末尾无需额外介词；guide 与 path 分别为其对象。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-039">回看讲解和练习</a></p><h2 id="l40-·-反身代词与相互代词" tabindex="-1">L40 · 反身代词与相互代词 <a class="header-anchor" href="#l40-·-反身代词与相互代词" aria-label="Permalink to &quot;L40 · 反身代词与相互代词 {#l40-·-反身代词与相互代词}&quot;">​</a></h2><p>They looked at themselves 表示看自己，looked at each other 表示彼此对视，不能互换。</p><p><strong>对照例句：</strong> The two actors introduced themselves before they introduced each other to the director.</p><p>themselves 回指各自，each other 表示相互对象；两个短语改变动作方向。</p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-040">回看讲解和练习</a></p><h2 id="l41-·-while-与-whereas-的对照" tabindex="-1">L41 · while 与 whereas 的对照 <a class="header-anchor" href="#l41-·-while-与-whereas-的对照" aria-label="Permalink to &quot;L41 · while 与 whereas 的对照 {#l41-·-while-与-whereas-的对照}&quot;">​</a></h2><p>while 不能每次都译作“当……时”；While Anna likes silence, Ben enjoys company 中表达的是偏好对照。</p><p><strong>对照例句：</strong> The village is quiet after sunset, whereas the market town remains busy until midnight.</p><p>whereas 对照两个地方在夜间的活动状态，不表示一个事件发生在另一个事件期间。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-041">回看讲解和练习</a></p><h2 id="l42-·-独立主格的独立主语" tabindex="-1">L42 · 独立主格的独立主语 <a class="header-anchor" href="#l42-·-独立主格的独立主语" aria-label="Permalink to &quot;L42 · 独立主格的独立主语 {#l42-·-独立主格的独立主语}&quot;">​</a></h2><p>The passage was blocked, the team returned 属于逗号拼接两个完整句，需加 so、用分号或改为从句。</p><p><strong>对照例句：</strong> The main passage blocked, the team returned to the entrance.</p><p>the main passage 为独立结构主语，blocked 表被动状态；主句主语为 the team。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-042">回看讲解和练习</a></p><h2 id="l43-·-provided-that-与-unless" tabindex="-1">L43 · provided that 与 unless <a class="header-anchor" href="#l43-·-provided-that-与-unless" aria-label="Permalink to &quot;L43 · provided that 与 unless {#l43-·-provided-that-与-unless}&quot;">​</a></h2><p>Unless you don&#39;t report it 会形成额外否定，若意为“如果不报告”，直接写 unless you report it。</p><p><strong>对照例句：</strong> In this fictional scheme, repairs are covered provided that the damage is reported within a week.</p><p>provided that 引出必要条件；within a week 给出时间限制，句子没有描述现实产品。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-043">回看讲解和练习</a></p><h2 id="l44-·-平行结构与-not-only" tabindex="-1">L44 · 平行结构与 not only <a class="header-anchor" href="#l44-·-平行结构与-not-only" aria-label="Permalink to &quot;L44 · 平行结构与 not only {#l44-·-平行结构与-not-only}&quot;">​</a></h2><p>both comfortable and saves time 不平行；可改为 both comfortable and convenient，或 It is comfortable and saves time。</p><p><strong>对照例句：</strong> The night train offers both a quiet place to sleep and a direct route to the city centre.</p><p>both ... and 连接两个名词短语，均为 offers 的宾语，语法层级一致。</p><p><a href="/life/english/new-concept/book-3/unit-03/lesson-044">回看讲解和练习</a></p>',118)])])}const g=a(i,[["render",s]]);export{u as __pageData,g as default};
